def simulate_nfa(s):
    # states: p,q,r,s
    cur = {'p'}
    for ch in s:
        nxt = set()
        for st in cur:
            if st == 'p':
                if ch == '1': nxt.add('q')
                else: nxt.add('p')
            elif st == 'q':
                if ch == '0': nxt.add('r')
                else: nxt.add('q')
            elif st == 'r':
                if ch == '1': nxt.add('s')
                else: nxt.add('p')
            elif st == 's':
                nxt.add('s')
        cur = nxt
    return 'Accepted' if 's' in cur else 'Rejected'
print(simulate_nfa('110101'))

